// Aus den Rohzählern des Relays wird eine Zeile, die ein Mensch in drei Sekunden liest.
const daten = $json;
const heute = daten.days?.[0] ?? { day: 'unbekannt', counts: {}, total: 0 };
const z = heute.counts ?? {};

const angenommen = z['relay.accepted'] ?? 0;
const duplikate  = z['relay.duplicate'] ?? 0;
const ga4Gesendet   = z['ga4.sent'] ?? 0;
const ga4Fehler     = z['ga4.failed'] ?? 0;
const capiGesendet  = z['capi.sent'] ?? 0;
const capiFehler    = z['capi.failed'] ?? 0;
const übersprungen = (z['ga4.skipped'] ?? 0) + (z['capi.skipped'] ?? 0);

const fehlerGesamt = ga4Fehler + capiFehler;

// Die Zustellquote bezieht sich auf die Zustellversuche, nicht auf alle Ereignisse. Ein Ziel, das
// wegen fehlender Einwilligung oder fehlender Einrichtung bewusst übersprungen wurde, ist kein
// Fehlschlag und darf die Quote nicht nach unten ziehen.
const versucht = ga4Gesendet + ga4Fehler + capiGesendet + capiFehler;
const zustellquote = versucht > 0
  ? Math.round(((ga4Gesendet + capiGesendet) / versucht) * 100)
  : 100;

// Die Dublettenquote ist die eigentlich interessante Zahl. Steigt sie plötzlich, stimmt etwas
// mit dem Tag-Aufbau nicht, zum Beispiel ein Tag, der zweimal feuert.
const dublettenquote = (angenommen + duplikate) > 0
  ? Math.round((duplikate / (angenommen + duplikate)) * 100)
  : 0;

return [{
  json: {
    tag: heute.day,
    angenommen,
    duplikate,
    dublettenquote_prozent: dublettenquote,
    ga4_gesendet: ga4Gesendet,
    ga4_fehler: ga4Fehler,
    capi_gesendet: capiGesendet,
    capi_fehler: capiFehler,
    übersprungen,
    zustellversuche: versucht,
    zustellquote_prozent: zustellquote,
    fehler_gesamt: fehlerGesamt,
    zusammenfassung:
      `${heute.day}: ${angenommen} angenommen, ${duplikate} Duplikate (${dublettenquote} Prozent), `
      + `GA4 ${ga4Gesendet} gesendet / ${ga4Fehler} Fehler, CAPI ${capiGesendet} gesendet / ${capiFehler} Fehler, `
      + `${übersprungen} übersprungen, Zustellquote ${zustellquote} Prozent.`,
  },
}];
